    loans:['https://afe.easia.columbia.edu/main_pop/ps/ps_china-wang-anshi-crop-loans.htm','Wang Anshi · Memorial on crop loans, Columbia translation'],
    money:['https://afe.easia.columbia.edu/songdynasty-module/econ-rev-money.html','Columbia University · From coins to paper money'],
    shen:['https://afe.easia.columbia.edu/songdynasty-module/tech-experiment.html','Columbia University · Shen Kuo and technical inquiry'],
    zhu:['https://plato.stanford.edu/entries/zhu-xi/','Stanford Encyclopedia of Philosophy · Zhu Xi'],
    wang:['https://plato.stanford.edu/entries/wang-yangming/','Stanford Encyclopedia of Philosophy · Wang Yangming'],
    port:['https://whc.unesco.org/en/list/1561','UNESCO · Quanzhou: Emporium of the World'],
    portdate:['https://whc.unesco.org/document/189212','ICOMOS · Quanzhou evaluation and 1087 trade office'],
    vases:['https://www.britishmuseum.org/collection/object/A_PDF-B-614','British Museum · Inscribed David vase, 1351'],
